213	void GazeboRosAckermannDrive::Load(gazebo::physics::ModelPtr _model, sdf::ElementPtr _sdf)
214	{
215	  impl_->model_ = _model;
216	
217	  auto world = impl_->model_->GetWorld();
218	  auto physicsEngine = world->Physics();
219	  physicsEngine->SetParam("friction_model", std::string("cone_model"));
220	
221	  // Initialize ROS node
222	  impl_->ros_node_ = gazebo_ros::Node::Get(_sdf);
223	
224	  // Get QoS profiles
225	  const gazebo_ros::QoS & qos = impl_->ros_node_->get_qos();
226	
227	  impl_->joints_.resize(7);
228	
229	  auto steering_wheel_joint =
230	    _sdf->Get<std::string>("steering_wheel_joint", "steering_wheel_joint").first;
231	  impl_->joints_[GazeboRosAckermannDrivePrivate::STEER_WHEEL] =
232	    _model->GetJoint(steering_wheel_joint);
233	  if (!impl_->joints_[GazeboRosAckermannDrivePrivate::STEER_WHEEL]) {
234	    RCLCPP_WARN(
235	      impl_->ros_node_->get_logger(),
236	      "Steering wheel joint [%s] not found.", steering_wheel_joint.c_str());
237	    impl_->joints_.resize(6);
238	  }
239	
240	  auto front_right_joint = _sdf->Get<std::string>("front_right_joint", "front_right_joint").first;
241	  impl_->joints_[GazeboRosAckermannDrivePrivate::FRONT_RIGHT] = _model->GetJoint(front_right_joint);
242	  if (!impl_->joints_[GazeboRosAckermannDrivePrivate::FRONT_RIGHT]) {
243	    RCLCPP_ERROR(
244	      impl_->ros_node_->get_logger(),
245	      "Front right wheel joint [%s] not found, plugin will not work.", front_right_joint.c_str());
246	    impl_->ros_node_.reset();
247	    return;
248	  }
249	
250	  auto front_left_joint = _sdf->Get<std::string>("front_left_joint", "front_left_joint").first;
251	  impl_->joints_[GazeboRosAckermannDrivePrivate::FRONT_LEFT] = _model->GetJoint(front_left_joint);
252	  if (!impl_->joints_[GazeboRosAckermannDrivePrivate::FRONT_LEFT]) {
253	    RCLCPP_ERROR(
254	      impl_->ros_node_->get_logger(),
255	      "Front left wheel joint [%s] not found, plugin will not work.", front_left_joint.c_str());
256	    impl_->ros_node_.reset();
257	    return;
258	  }
259	
260	  auto rear_right_joint = _sdf->Get<std::string>("rear_right_joint", "rear_right_joint").first;
261	  impl_->joints_[GazeboRosAckermannDrivePrivate::REAR_RIGHT] = _model->GetJoint(rear_right_joint);
262	  if (!impl_->joints_[GazeboRosAckermannDrivePrivate::REAR_RIGHT]) {
263	    RCLCPP_ERROR(
264	      impl_->ros_node_->get_logger(),
265	      "Rear right wheel joint [%s] not found, plugin will not work.", rear_right_joint.c_str());
266	    impl_->ros_node_.reset();
267	    return;
268	  }
269	
270	  auto rear_left_joint = _sdf->Get<std::string>("rear_left_joint", "rear_left_joint").first;
271	  impl_->joints_[GazeboRosAckermannDrivePrivate::REAR_LEFT] = _model->GetJoint(rear_left_joint);
272	  if (!impl_->joints_[GazeboRosAckermannDrivePrivate::REAR_LEFT]) {
273	    RCLCPP_ERROR(
274	      impl_->ros_node_->get_logger(),
275	      "Rear left wheel joint [%s] not found, plugin will not work.", rear_left_joint.c_str());
276	    impl_->ros_node_.reset();
277	    return;
278	  }
279	
280	  auto right_steering_joint =
281	    _sdf->Get<std::string>("right_steering_joint", "right_steering_joint").first;
282	  impl_->joints_[GazeboRosAckermannDrivePrivate::STEER_RIGHT] =
283	    _model->GetJoint(right_steering_joint);
284	  if (!impl_->joints_[GazeboRosAckermannDrivePrivate::STEER_RIGHT]) {
285	    RCLCPP_ERROR(
286	      impl_->ros_node_->get_logger(),
287	      "Right wheel steering joint [%s] not found, plugin will not work.",
288	      right_steering_joint.c_str());
289	    impl_->ros_node_.reset();
290	    return;
291	  }
292	
293	  auto left_steering_joint =
294	    _sdf->Get<std::string>("left_steering_joint", "left_steering_joint").first;
295	  impl_->joints_[GazeboRosAckermannDrivePrivate::STEER_LEFT] =
296	    _model->GetJoint(left_steering_joint);
297	  if (!impl_->joints_[GazeboRosAckermannDrivePrivate::STEER_LEFT]) {
298	    RCLCPP_ERROR(
299	      impl_->ros_node_->get_logger(),
300	      "Left wheel steering joint [%s] not found, plugin will not work.",
301	      left_steering_joint.c_str());
302	    impl_->ros_node_.reset();
303	    return;
304	  }
305	
306	  impl_->max_speed_ = _sdf->Get<double>("max_speed", 20.0).first;
307	  impl_->max_steer_ = _sdf->Get<double>("max_steer", 0.6).first;
308	
309	  // Max the steering wheel can rotate
310	  auto max_steering_angle = _sdf->Get<double>("max_steering_angle", 7.85).first;
311	
312	  // Compute the angle ratio between the steering wheel and the tires
313	  impl_->steering_ratio_ = impl_->max_steer_ / max_steering_angle;
314	
315	  auto pid = _sdf->Get<ignition::math::Vector3d>(
316	    "right_steering_pid_gain", ignition::math::Vector3d::Zero).first;
317	  auto i_range = _sdf->Get<ignition::math::Vector2d>(
318	    "right_steering_i_range", ignition::math::Vector2d::Zero).first;
319	  impl_->pid_right_steering_.Init(pid.X(), pid.Y(), pid.Z(), i_range.Y(), i_range.X());
320	
321	  pid = _sdf->Get<ignition::math::Vector3d>(
322	    "left_steering_pid_gain", ignition::math::Vector3d::Zero).first;
323	  i_range = _sdf->Get<ignition::math::Vector2d>(
324	    "left_steering_i_range", ignition::math::Vector2d::Zero).first;
325	  impl_->pid_left_steering_.Init(pid.X(), pid.Y(), pid.Z(), i_range.Y(), i_range.X());
326	
327	  pid = _sdf->Get<ignition::math::Vector3d>(
328	    "linear_velocity_pid_gain", ignition::math::Vector3d::Zero).first;
329	  i_range = _sdf->Get<ignition::math::Vector2d>(
330	    "linear_velocity_i_range", ignition::math::Vector2d::Zero).first;
331	  impl_->pid_linear_vel_.Init(pid.X(), pid.Y(), pid.Z(), i_range.Y(), i_range.X());
332	
333	  // Update wheel radiu for wheel from SDF collision objects
334	  // assumes that wheel link is child of joint (and not parent of joint)
335	  // assumes that wheel link has only one collision
336	  // assumes all wheel of both rear wheels of same radii
337	  unsigned int id = 0;
338	  impl_->wheel_radius_ = impl_->CollisionRadius(
339	    impl_->joints_[GazeboRosAckermannDrivePrivate::REAR_RIGHT]->GetChild()->GetCollision(id));
340	
341	  // Compute wheel_base, front wheel separation, and rear wheel separation
342	  // first compute the positions of the 4 wheel centers
343	  // again assumes wheel link is child of joint and has only one collision
344	  auto front_right_center_pos = impl_->joints_[GazeboRosAckermannDrivePrivate::FRONT_RIGHT]->
345	    GetChild()->GetCollision(id)->WorldPose().Pos();
346	  auto front_left_center_pos = impl_->joints_[GazeboRosAckermannDrivePrivate::FRONT_LEFT]->
347	    GetChild()->GetCollision(id)->WorldPose().Pos();
348	  auto rear_right_center_pos = impl_->joints_[GazeboRosAckermannDrivePrivate::REAR_RIGHT]->
349	    GetChild()->GetCollision(id)->WorldPose().Pos();
350	  auto rear_left_center_pos = impl_->joints_[GazeboRosAckermannDrivePrivate::REAR_LEFT]->
351	    GetChild()->GetCollision(id)->WorldPose().Pos();
352	
353	  auto distance = front_left_center_pos - front_right_center_pos;
354	  impl_->wheel_separation_ = distance.Length();
355	
356	  // to compute wheelbase, first position of axle centers are computed
357	  auto front_axle_pos = (front_left_center_pos + front_right_center_pos) / 2;
358	  auto rear_axle_pos = (rear_left_center_pos + rear_right_center_pos) / 2;
359	  // then the wheelbase is the distance between the axle centers
360	  distance = front_axle_pos - rear_axle_pos;
361	  impl_->wheel_base_ = distance.Length();
362	
363	  // Update rate
364	  auto update_rate = _sdf->Get<double>("update_rate", 100.0).first;
365	  if (update_rate > 0.0) {
366	    impl_->update_period_ = 1.0 / update_rate;
367	  } else {
368	    impl_->update_period_ = 0.0;
369	  }
370	  impl_->last_update_time_ = _model->GetWorld()->SimTime();
371	
372	  impl_->cmd_vel_sub_ = impl_->ros_node_->create_subscription<geometry_msgs::msg::Twist>(
373	    "cmd_vel", qos.get_subscription_qos("cmd_vel", rclcpp::QoS(1)),
374	    std::bind(&GazeboRosAckermannDrivePrivate::OnCmdVel, impl_.get(), std::placeholders::_1));
375	
376	  RCLCPP_INFO(
377	    impl_->ros_node_->get_logger(), "Subscribed to [%s]", impl_->cmd_vel_sub_->get_topic_name());
378	
379	  // Odometry
380	  impl_->odometry_frame_ = _sdf->Get<std::string>("odometry_frame", "odom").first;
381	  impl_->robot_base_frame_ = _sdf->Get<std::string>("robot_base_frame", "base_footprint").first;
382	
383	  // Advertise odometry topic
384	  impl_->publish_odom_ = _sdf->Get<bool>("publish_odom", false).first;
385	  if (impl_->publish_odom_) {
386	    impl_->odometry_pub_ = impl_->ros_node_->create_publisher<nav_msgs::msg::Odometry>(
387	      "odom", qos.get_publisher_qos("odom", rclcpp::QoS(1)));
388	
389	    RCLCPP_INFO(
390	      impl_->ros_node_->get_logger(), "Advertise odometry on [%s]",
391	      impl_->odometry_pub_->get_topic_name());
392	  }
393	
394	  // Advertise distance travelled
395	  impl_->publish_distance_ = _sdf->Get<bool>("publish_distance", false).first;
396	  if (impl_->publish_distance_) {
397	    impl_->distance_pub_ = impl_->ros_node_->create_publisher<std_msgs::msg::Float32>(
398	      "distance", qos.get_publisher_qos("distance", rclcpp::QoS(1)));
399	
400	    RCLCPP_INFO(
401	      impl_->ros_node_->get_logger(), "Advertise distance on [%s]",
402	      impl_->distance_pub_->get_topic_name());
403	  }
404	
405	  // Advertise steering angle
406	  impl_->publish_steerangle_ = _sdf->Get<bool>("publish_steerangle", false).first;
407	  if (impl_->publish_steerangle_) {
408	    impl_->steerangle_pub_ = impl_->ros_node_->create_publisher<std_msgs::msg::Float32>(
409	      "steerangle", qos.get_publisher_qos("steerangle", rclcpp::QoS(1)));
410	
411	    RCLCPP_INFO(
412	      impl_->ros_node_->get_logger(), "Advertise steerangle on [%s]",
413	      impl_->steerangle_pub_->get_topic_name());
414	  }
415	
416	  // Create TF broadcaster if needed
417	  impl_->publish_wheel_tf_ = _sdf->Get<bool>("publish_wheel_tf", false).first;
418	  impl_->publish_odom_tf_ = _sdf->Get<bool>("publish_odom_tf", false).first;
419	  if (impl_->publish_wheel_tf_ || impl_->publish_odom_tf_) {
420	    impl_->transform_broadcaster_ =
421	      std::make_shared<tf2_ros::TransformBroadcaster>(impl_->ros_node_);
422	
423	    if (impl_->publish_odom_tf_) {
424	      RCLCPP_INFO(
425	        impl_->ros_node_->get_logger(),
426	        "Publishing odom transforms between [%s] and [%s]", impl_->odometry_frame_.c_str(),
427	        impl_->robot_base_frame_.c_str());
428	    }
429	
430	    if (impl_->publish_wheel_tf_) {
431	      for (auto & joint : impl_->joints_) {
432	        RCLCPP_INFO(
433	          impl_->ros_node_->get_logger(),
434	          "Publishing wheel transforms between [%s], [%s] and [%s]",
435	          impl_->robot_base_frame_.c_str(), joint->GetName().c_str(), joint->GetName().c_str());
436	      }
437	    }
438	  }
439	
440	  auto pose = impl_->model_->WorldPose();
441	  impl_->odom_.pose.pose.position = gazebo_ros::Convert<geometry_msgs::msg::Point>(pose.Pos());
442	  impl_->odom_.pose.pose.orientation = gazebo_ros::Convert<geometry_msgs::msg::Quaternion>(
443	    pose.Rot());
444	
445	  impl_->covariance_[0] = _sdf->Get<double>("covariance_x", 0.00001).first;
446	  impl_->covariance_[1] = _sdf->Get<double>("covariance_y", 0.00001).first;
447	  impl_->covariance_[2] = _sdf->Get<double>("covariance_yaw", 0.001).first;
448	
449	  // Listen to the update event (broadcast every simulation iteration)
450	  impl_->update_connection_ = gazebo::event::Events::ConnectWorldUpdateBegin(
451	    std::bind(&GazeboRosAckermannDrivePrivate::OnUpdate, impl_.get(), std::placeholders::_1));
452	}
