464	void GazeboRosAckermannDrivePrivate::OnUpdate(const gazebo::common::UpdateInfo & _info)
465	{
466	  #ifdef IGN_PROFILER_ENABLE
467	  IGN_PROFILE("GazeboRosAckermannDrivePrivate::OnUpdate");
468	  #endif
469	  std::lock_guard<std::mutex> lock(lock_);
470	
471	  double seconds_since_last_update = (_info.simTime - last_update_time_).Double();
472	
473	#ifdef IGN_PROFILER_ENABLE
474	  IGN_PROFILE_BEGIN("UpdateOdometryWorld");
475	#endif
476	  // Update odom
477	  UpdateOdometryWorld();
478	#ifdef IGN_PROFILER_ENABLE
479	  IGN_PROFILE_END();
480	#endif
481	  if (seconds_since_last_update < update_period_) {
482	    return;
483	  }
484	
485	  if (publish_distance_) {
486	#ifdef IGN_PROFILER_ENABLE
487	    IGN_PROFILE_BEGIN("publish distance");
488	#endif
489	    distance_pub_->publish(distance_);
490	#ifdef IGN_PROFILER_ENABLE
491	    IGN_PROFILE_END();
492	#endif
493	  }
494	
495	  if (publish_odom_) {
496	#ifdef IGN_PROFILER_ENABLE
497	    IGN_PROFILE_BEGIN("PublishOdometryMsg");
498	#endif
499	    PublishOdometryMsg(_info.simTime);
500	#ifdef IGN_PROFILER_ENABLE
501	    IGN_PROFILE_END();
502	#endif
503	  }
504	
505	  if (publish_wheel_tf_) {
506	#ifdef IGN_PROFILER_ENABLE
507	    IGN_PROFILE_BEGIN("PublishWheelsTf");
508	#endif
509	    PublishWheelsTf(_info.simTime);
510	#ifdef IGN_PROFILER_ENABLE
511	    IGN_PROFILE_END();
512	#endif
513	  }
514	
515	  if (publish_odom_tf_) {
516	#ifdef IGN_PROFILER_ENABLE
517	    IGN_PROFILE_BEGIN("PublishOdometryTf");
518	#endif
519	    PublishOdometryTf(_info.simTime);
520	#ifdef IGN_PROFILER_ENABLE
521	    IGN_PROFILE_END();
522	#endif
523	  }
524	
525	#ifdef IGN_PROFILER_ENABLE
526	  IGN_PROFILE_BEGIN("update");
527	#endif
528	  // Current speed assuming equal for left rear and right rear
529	  auto linear_vel = joints_[REAR_RIGHT]->GetVelocity(0);
530	  auto target_linear = ignition::math::clamp(target_linear_, -max_speed_, max_speed_);
531	  double linear_diff = linear_vel - target_linear / wheel_radius_;
532	  double linear_cmd = pid_linear_vel_.Update(linear_diff, seconds_since_last_update);
533	
534	  auto target_rot = target_rot_ * copysign(1.0, target_linear_);
535	  target_rot = ignition::math::clamp(target_rot, -max_steer_, max_steer_);
536	
537	  double tanSteer = tan(target_rot);
538	
539	  auto target_left_steering =
540	    atan2(tanSteer, 1.0 - wheel_separation_ / 2.0 / wheel_base_ * tanSteer);
541	  auto target_right_steering =
542	    atan2(tanSteer, 1.0 + wheel_separation_ / 2.0 / wheel_base_ * tanSteer);
543	
544	  auto left_steering_angle = joints_[STEER_LEFT]->Position(0);
545	  auto right_steering_angle = joints_[STEER_RIGHT]->Position(0);
546	
547	  double left_steering_diff = left_steering_angle - target_left_steering;
548	  double left_steering_cmd =
549	    pid_left_steering_.Update(left_steering_diff, seconds_since_last_update);
550	
551	  double right_steering_diff = right_steering_angle - target_right_steering;
552	  double right_steering_cmd =
553	    pid_right_steering_.Update(right_steering_diff, seconds_since_last_update);
554	
555	  auto steer_wheel_angle = (left_steering_angle + right_steering_angle) * 0.5 / steering_ratio_;
556	  steerangle_.data = (left_steering_angle + right_steering_angle) * 0.5;
557	
558	  if (publish_steerangle_) {
559	#ifdef IGN_PROFILER_ENABLE
560	    IGN_PROFILE_BEGIN("publish steerangle");
561	#endif
562	    steerangle_pub_->publish(steerangle_);
563	#ifdef IGN_PROFILER_ENABLE
564	    IGN_PROFILE_END();
565	#endif
566	  }
567	
568	  joints_[STEER_LEFT]->SetForce(0, left_steering_cmd);
569	  joints_[STEER_RIGHT]->SetForce(0, right_steering_cmd);
570	  joints_[REAR_RIGHT]->SetForce(0, linear_cmd);
571	  joints_[REAR_LEFT]->SetForce(0, linear_cmd);
572	
573	  if (joints_.size() == 7) {
574	    joints_[STEER_WHEEL]->SetPosition(0, steer_wheel_angle);
575	  }
576	
577	  last_update_time_ = _info.simTime;
578	  #ifdef IGN_PROFILER_ENABLE
579	  IGN_PROFILE_END();
580	  #endif
581	}
582	
583	void GazeboRosAckermannDrivePrivate::OnCmdVel(const geometry_msgs::msg::Twist::SharedPtr _msg)
584	{
585	  std::lock_guard<std::mutex> scoped_lock(lock_);
586	  target_linear_ = _msg->linear.x;
587	  target_rot_ = _msg->angular.z;
588	}
589	
590	double GazeboRosAckermannDrivePrivate::CollisionRadius(const gazebo::physics::CollisionPtr & _coll)
591	{
592	  if (!_coll || !(_coll->GetShape())) {
593	    return 0;
594	  }
595	  if (_coll->GetShape()->HasType(gazebo::physics::Base::CYLINDER_SHAPE)) {
596	    gazebo::physics::CylinderShape * cyl =
597	      dynamic_cast<gazebo::physics::CylinderShape *>(_coll->GetShape().get());
598	    return cyl->GetRadius();
599	  } else if (_coll->GetShape()->HasType(gazebo::physics::Base::SPHERE_SHAPE)) {
600	    gazebo::physics::SphereShape * sph =
601	      dynamic_cast<gazebo::physics::SphereShape *>(_coll->GetShape().get());
602	    return sph->GetRadius();
603	  }
604	  return 0;
605	}
606	
607	void GazeboRosAckermannDrivePrivate::UpdateOdometryWorld()
608	{
609	  auto prev_x = odom_.pose.pose.position.x;
610	  auto prev_y = odom_.pose.pose.position.y;
611	
612	  auto pose = model_->WorldPose();
613	  odom_.pose.pose.position = gazebo_ros::Convert<geometry_msgs::msg::Point>(pose.Pos());
614	  odom_.pose.pose.orientation = gazebo_ros::Convert<geometry_msgs::msg::Quaternion>(pose.Rot());
615	
616	  distance_.data += hypot(prev_x - odom_.pose.pose.position.x, prev_y - odom_.pose.pose.position.y);
617	
618	  // Get velocity in odom frame
619	  auto linear = model_->WorldLinearVel();
620	  odom_.twist.twist.angular.z = model_->WorldAngularVel().Z();
621	
622	  // Convert velocity to child_frame_id(aka base_footprint)
623	  auto yaw = static_cast<float>(pose.Rot().Yaw());
624	  odom_.twist.twist.linear.x = cosf(yaw) * linear.X() + sinf(yaw) * linear.Y();
625	  odom_.twist.twist.linear.y = cosf(yaw) * linear.Y() - sinf(yaw) * linear.X();
626	}
627	
628	void GazeboRosAckermannDrivePrivate::PublishOdometryTf(const gazebo::common::Time & _current_time)
629	{
630	  geometry_msgs::msg::TransformStamped msg;
631	  msg.header.stamp = gazebo_ros::Convert<builtin_interfaces::msg::Time>(_current_time);
632	  msg.header.frame_id = odometry_frame_;
633	  msg.child_frame_id = robot_base_frame_;
634	  msg.transform.translation =
635	    gazebo_ros::Convert<geometry_msgs::msg::Vector3>(odom_.pose.pose.position);
636	  msg.transform.rotation = odom_.pose.pose.orientation;
637	
638	  transform_broadcaster_->sendTransform(msg);
639	}
640	
641	void GazeboRosAckermannDrivePrivate::PublishWheelsTf(const gazebo::common::Time & _current_time)
642	{
643	  for (const auto & joint : joints_) {
644	    auto pose = joint->GetChild()->WorldPose() - model_->WorldPose();
645	
646	    geometry_msgs::msg::TransformStamped msg;
647	    msg.header.stamp = gazebo_ros::Convert<builtin_interfaces::msg::Time>(_current_time);
648	    msg.header.frame_id = robot_base_frame_;
649	    msg.child_frame_id = joint->GetChild()->GetName();
650	    msg.transform.translation = gazebo_ros::Convert<geometry_msgs::msg::Vector3>(pose.Pos());
651	    msg.transform.rotation = gazebo_ros::Convert<geometry_msgs::msg::Quaternion>(pose.Rot());
652	
653	    transform_broadcaster_->sendTransform(msg);
654	  }
655	}
656	
657	void GazeboRosAckermannDrivePrivate::PublishOdometryMsg(const gazebo::common::Time & _current_time)
658	{
659	  // Set covariance
660	  odom_.pose.covariance[0] = covariance_[0];
661	  odom_.pose.covariance[7] = covariance_[1];
662	  odom_.pose.covariance[14] = 1000000000000.0;
663	  odom_.pose.covariance[21] = 1000000000000.0;
664	  odom_.pose.covariance[28] = 1000000000000.0;
665	  odom_.pose.covariance[35] = covariance_[2];
666	
667	  odom_.twist.covariance[0] = covariance_[0];
668	  odom_.twist.covariance[7] = covariance_[1];
669	  odom_.twist.covariance[14] = 1000000000000.0;
670	  odom_.twist.covariance[21] = 1000000000000.0;
671	  odom_.twist.covariance[28] = 1000000000000.0;
672	  odom_.twist.covariance[35] = covariance_[2];
673	
674	  // Set header
675	  odom_.header.frame_id = odometry_frame_;
676	  odom_.child_frame_id = robot_base_frame_;
677	  odom_.header.stamp = gazebo_ros::Convert<builtin_interfaces::msg::Time>(_current_time);
678	
679	  // Publish
680	  odometry_pub_->publish(odom_);
681	}
682	GZ_REGISTER_MODEL_PLUGIN(GazeboRosAckermannDrive)
683	}  // namespace gazebo_plugins
