7	#include <tf2/utils.h>
8	#include <tf2_geometry_msgs/tf2_geometry_msgs.hpp>
9	
10	namespace qcar_updated::smoothers
11	{
12	
13	void CuspStraightenerSmoother::configure(
14	  const rclcpp_lifecycle::LifecycleNode::WeakPtr & parent,
15	  std::string name,
16	  std::shared_ptr<tf2_ros::Buffer>/*tf*/,
17	  std::shared_ptr<nav2_costmap_2d::CostmapSubscriber>/*costmap_sub*/,
18	  std::shared_ptr<nav2_costmap_2d::FootprintSubscriber>/*footprint_sub*/)
19	{
20	  name_ = name;
21	  auto node = parent.lock();
22	  logger_ = node->get_logger();
23	  node->declare_parameter(name_ + ".straight_distance", straight_distance_);
24	  node->get_parameter(name_ + ".straight_distance", straight_distance_);
25	  node->declare_parameter(name_ + ".extend_distance", extend_distance_);
26	  node->get_parameter(name_ + ".extend_distance", extend_distance_);
27	  node->declare_parameter(name_ + ".min_lead_distance", min_lead_distance_);
28	  node->get_parameter(name_ + ".min_lead_distance", min_lead_distance_);
29	  RCLCPP_INFO(
30	    logger_, "CuspStraightenerSmoother instantiated with straight_distance %.3f, extend_distance %.3f, min_lead_distance %.3f",
31	    straight_distance_, extend_distance_, min_lead_distance_);
32	}
33	
34	bool CuspStraightenerSmoother::smooth(nav_msgs::msg::Path & path, const rclcpp::Duration &)
35	{
36	  const size_t n = path.poses.size();
37	  if (n < 3) {
38	    return true;
39	  }
40	
41	  // Read-only snapshot: every geometric decision below reads from `original`, never from `path`
42	  // itself (only ever written to). Needed because a replanned path can have multiple cusps close
43	  // together (e.g. a replan mid-maneuver) - processing cusps in place on a mutating array let an
44	  // earlier cusp's blend corrupt a later cusp's own classification/geometry (CHANGELOG.md 2026-08-26).
45	  const std::vector<geometry_msgs::msg::PoseStamped> original = path.poses;
46	
47	  // Find cusps: consecutive displacement vectors whose dot product is negative (direction of
48	  // travel reverses by more than 90 degrees) - same detection method used to analyze /plan CSVs
49	  // during the investigation that motivated this plugin.
50	  std::vector<size_t> cusp_indices;
51	  for (size_t i = 1; i + 1 < n; ++i) {
52	    const double d1x = original[i].pose.position.x - original[i - 1].pose.position.x;
53	    const double d1y = original[i].pose.position.y - original[i - 1].pose.position.y;
54	    const double d2x = original[i + 1].pose.position.x - original[i].pose.position.x;
55	    const double d2y = original[i + 1].pose.position.y - original[i].pose.position.y;
56	    const double len1 = std::hypot(d1x, d1y);
57	    const double len2 = std::hypot(d2x, d2y);
58	    if (len1 < 1e-6 || len2 < 1e-6) {
59	      continue;
60	    }
61	    const double dot = (d1x * d2x + d1y * d2y) / (len1 * len2);
62	    if (dot < 0.0) {
63	      cusp_indices.push_back(i);
64	    }
65	  }
66	  RCLCPP_INFO(logger_, "smooth(): path has %zu points, %zu cusp(s) detected", n, cusp_indices.size());
67	
68	  // Arc length from the path START (original[0], the robot's live pose on a replanned path) to
69	  // each point - needed below to tell a genuinely-upcoming K-turn cusp from one the robot has
70	  // essentially already reached (see min_lead_distance_ below).
71	  std::vector<double> lead_dist(n, 0.0);
72	  for (size_t i = 1; i < n; ++i) {
73	    lead_dist[i] = lead_dist[i - 1] + std::hypot(
74	      original[i].pose.position.x - original[i - 1].pose.position.x,
75	      original[i].pose.position.y - original[i - 1].pose.position.y);
76	  }
77	
78	  // Classify every cusp up front, read-only from `original` - independent of anything the loop
79	  // below builds into `output`.
80	  struct CuspInfo
81	  {
82	    size_t idx;
83	    bool reverse;
84	    double along;
85	    double lead_distance;
86	  };
87	  std::vector<CuspInfo> cusps;
88	  cusps.reserve(cusp_indices.size());
89	  for (const size_t cusp_i : cusp_indices) {
90	    const double cx = original[cusp_i].pose.position.x;
91	    const double cy = original[cusp_i].pose.position.y;
92	    const double cusp_yaw = tf2::getYaw(original[cusp_i].pose.orientation);
93	    const double dx = original[cusp_i + 1].pose.position.x - cx;
94	    const double dy = original[cusp_i + 1].pose.position.y - cy;
95	    const double along = dx * std::cos(cusp_yaw) + dy * std::sin(cusp_yaw);
96	    cusps.push_back({cusp_i, along < 0.0, along, lead_dist[cusp_i]});
97	  }
98	
99	  // Build a new output path rather than mutating `path.poses` in place, since a reverse-entering
100	  // cusp now INSERTS an extra point (the pushed-out corner) rather than only reshaping existing
101	  // ones. Walk through `original` in order, copying each point through, and at each
102	  // reverse-entering cusp: insert the extension point, then blend the following original points
103	  // (same taper as before) relative to that new point instead of the original cusp position -
104	  // pushing the corner outward so the reverse leg has to travel back past where the incoming
105	  // leg's overshoot was to rejoin the original downstream curve, rather than meeting it at one
106	  // precise vertex.
107	  std::vector<geometry_msgs::msg::PoseStamped> output;
108	  output.reserve(n + cusps.size() * 6);
109	
110	  size_t next_cusp = 0;
111	  for (size_t i = 0; i < n; ++i) {
112	    output.push_back(original[i]);
113	
114	    if (next_cusp < cusps.size() && cusps[next_cusp].idx == i) {
115	      const CuspInfo & c = cusps[next_cusp];
116	      if (!c.reverse) {
117	        RCLCPP_INFO(logger_, "  cusp at idx=%zu: forward-entering, skipped (along=%.4f)", i, c.along);
118	        ++next_cusp;
119	        continue;
120	      }
121	      if (c.lead_distance < min_lead_distance_) {
122	        // A replanned path starts at the robot's live pose, and this cusp reappears on every
123	        // replan while it's still ahead - once the robot is essentially already at/into it
124	        // (lead_distance this small), it's not an upcoming K-turn to prepare for anymore, it's
125	        // already underway. Re-extending it here would just reshape the path right under the
126	        // robot on every replan tick instead of a one-time approach adjustment.
127	        RCLCPP_INFO(
128	          logger_, "  cusp at idx=%zu: REVERSE-entering but only %.3fm ahead (< %.3fm) - robot already at/past it, skipped (along=%.4f)",
129	          i, c.lead_distance, min_lead_distance_, c.along);
130	        ++next_cusp;
131	        continue;
132	      }
133	      RCLCPP_INFO(
134	        logger_, "  cusp at idx=%zu: REVERSE-entering, extending corner by %.3f (curve-continuing) then straightening (along=%.4f)",
135	        i, extend_distance_, c.along);
136	
137	      const double cusp_yaw = tf2::getYaw(original[i].pose.orientation);
138	      const double cx = original[i].pose.position.x;
139	      const double cy = original[i].pose.position.y;
140	
141	      // Estimate the incoming leg's curvature right at the cusp from the yaw change over its
142	      // last segment, so the extension continues that curve instead of cutting straight.
143	      double kappa = 0.0;
144	      {
145	        const double prev_yaw = tf2::getYaw(original[i - 1].pose.orientation);
146	        const double ds = std::hypot(
147	          cx - original[i - 1].pose.position.x, cy - original[i - 1].pose.position.y);
148	        if (ds > 1e-6) {
149	          const double dyaw = std::atan2(std::sin(cusp_yaw - prev_yaw), std::cos(cusp_yaw - prev_yaw));
150	          kappa = dyaw / ds;
151	        }
152	      }
153	
154	      // Walk the extension in fixed-size sub-steps along that constant-curvature arc (straight
155	      // line when kappa ~ 0) so the curvature is actually visible to downstream path consumers
156	      // as multiple poses, not just implied by one endpoint.
157	      constexpr double kExtensionStep = 0.03;
158	      const int extension_steps = std::max(1, static_cast<int>(std::round(extend_distance_ / kExtensionStep)));
159	      const double step = extend_distance_ / extension_steps;
160	      double ex = cx, ey = cy, ext_yaw = cusp_yaw;
161	      for (int s = 1; s <= extension_steps; ++s) {
162	        const double arc = step * s;
163	        double px, py;
164	        if (std::abs(kappa) > 1e-6) {
165	          const double radius = 1.0 / kappa;
166	          px = cx + radius * (std::sin(cusp_yaw + kappa * arc) - std::sin(cusp_yaw));
167	          py = cy - radius * (std::cos(cusp_yaw + kappa * arc) - std::cos(cusp_yaw));
168	        } else {
169	          px = cx + std::cos(cusp_yaw) * arc;
170	          py = cy + std::sin(cusp_yaw) * arc;
171	        }
172	        ext_yaw = cusp_yaw + kappa * arc;
173	
174	        geometry_msgs::msg::PoseStamped ext_pose = original[i];
175	        ext_pose.pose.position.x = px;
176	        ext_pose.pose.position.y = py;
177	        tf2::Quaternion ext_q;
178	        ext_q.setRPY(0, 0, ext_yaw);
179	        ext_pose.pose.orientation = tf2::toMsg(ext_q);
180	        output.push_back(ext_pose);
181	        ex = px;
182	        ey = py;
183	      }
184	
185	      // Blend subsequent original points relative to the NEW extended point (ex, ey) as the
186	      // reverse leg's own straight-run origin - same taper as before (weight 1.0 at the
187	      // extension point, fading to 0.0 at straight_distance_), just re-anchored, and now running
188	      // opposite the extension's own end heading (ext_yaw) rather than the original cusp heading,
189	      // since that's the direction the vehicle is actually facing once it reaches (ex, ey).
190	      const double ux = -std::cos(ext_yaw);
191	      const double uy = -std::sin(ext_yaw);
192	      double cumulative = 0.0;
193	      double prev_x = ex;
194	      double prev_y = ey;
195	      size_t j = i + 1;
196	      while (j < n && cumulative < straight_distance_) {
197	        // Don't blend across the next cusp - let it be handled by its own iteration.
198	        if (next_cusp + 1 < cusps.size() && cusps[next_cusp + 1].idx == j) {
199	          break;
200	        }
201	        const double orig_x = original[j].pose.position.x;
202	        const double orig_y = original[j].pose.position.y;
203	        const double orig_yaw = tf2::getYaw(original[j].pose.orientation);
204	        const double seg_dx = orig_x - prev_x;
205	        const double seg_dy = orig_y - prev_y;
206	        prev_x = orig_x;
207	        prev_y = orig_y;
208	        cumulative += std::hypot(seg_dx, seg_dy);
209	
210	        const double weight = std::clamp(1.0 - cumulative / straight_distance_, 0.0, 1.0);
211	        const double straight_x = ex + ux * cumulative;
212	        const double straight_y = ey + uy * cumulative;
213	        const double yaw_diff = std::atan2(
214	          std::sin(orig_yaw - ext_yaw), std::cos(orig_yaw - ext_yaw));
215	        const double blended_yaw = ext_yaw + (1.0 - weight) * yaw_diff;
216	
217	        geometry_msgs::msg::PoseStamped blended = original[j];
218	        blended.pose.position.x = weight * straight_x + (1.0 - weight) * orig_x;
219	        blended.pose.position.y = weight * straight_y + (1.0 - weight) * orig_y;
220	        tf2::Quaternion blended_q;
221	        blended_q.setRPY(0, 0, blended_yaw);
222	        blended.pose.orientation = tf2::toMsg(blended_q);
223	        output.push_back(blended);
224	        ++j;
225	      }
226	
227	      i = j - 1;  // outer loop's ++i resumes at j next iteration
228	      ++next_cusp;
229	    }
230	  }
231	
232	  path.poses = std::move(output);
233	  return true;
234	}
235	
236	}  // namespace qcar_updated::smoothers
237	
